\begin{theorem}[单调次模最大化的贪心界]
\label{thm:comb-greedy-submodular}
设$1\leq k\leq|V|$，$F$归一化、单调且次模，$S^\star$是在
$|S|\leq k$下的最优解。
上述贪心算法运行$k$步得到$S^{(k)}$，则
\begin{equation}
  F(S^{(k)})
  \geq
  \left(1-\left(1-\frac1k\right)^k\right)F(S^\star)
  \geq(1-e^{-1})F(S^\star).
  \label{eq:comb-greedy-bound}
\end{equation}
\end{theorem}

\begin{equation}
  F^\star:=\max_{S\in\mathcal C}F(S)
  \leq U^\star:=\sup_{\bm z\in P}G(\bm z).
  \label{eq:comb-relaxation-upper-bound}
\end{equation}

\begin{equation}
  L\leq F^\star\leq U,\qquad
  0\leq F^\star-F(\widehat S)\leq U-L.
  \label{eq:comb-relaxation-certificate}
\end{equation}

